function lowestCommonAncestor(root, p, q) {
    // Base Case: If the root is null or matches either target node p or q
    if (!root || root === p || root === q) {
        return root;
    }

    // Recursively search the left and right subtrees
    const left = lowestCommonAncestor(root.left, p, q);
    const right = lowestCommonAncestor(root.right, p, q);

    // If both subtrees returned a non-null node, p and q were found in 
    // different subtrees, meaning this root is their Lowest Common Ancestor
    if (left !== null && right !== null) {
        return root;
    }

    // Otherwise, return the non-null result (propagate the found node upwards)
    return left !== null ? left : right;
}

